  cmpBootstrapping: ["Bootstrapping intervals…", "부트스트랩으로 신뢰구간을 계산하는 중…", "正在用自助法计算区间…", "ブートストラップで区間を計算中…", "Calculando intervalos por bootstrap…", "Calcul des intervalles par bootstrap…"],
  cmpFailed: ["Comparison failed", "비교에 실패했습니다", "比较失败", "比較に失敗しました", "La comparación falló", "Échec de la comparaison"],
  cmpComparing: ["Comparing the runs…", "실행을 비교하는 중…", "正在比较运行…", "実行を比較しています…", "Comparando las simulaciones…", "Comparaison des simulations…"],
  cmpExplain: ["Explain the difference", "차이 설명 보기", "解释差异", "差を説明", "Explicar la diferencia", "Expliquer l’écart"],
  cmpExplainHint: ["A model compares both runs shelf by shelf and hour by hour.", "모델이 두 실행을 선반별, 시간대별로 비교합니다.", "模型会逐个货架、逐小时比较两次运行。", "モデルが2つの実行を棚ごと・時間ごとに比較します。", "Un modelo compara ambas simulaciones estante por estante y hora por hora.", "Un modèle compare les deux simulations rayon par rayon et heure par heure."],
  cmpWhyDiffer: ["Why the runs differ", "실행 결과가 다른 이유", "两次运行为何不同", "実行結果が異なる理由", "Por qué difieren las simulaciones", "Pourquoi les simulations diffèrent"],
  cmpMetricsRegion: ["Run comparison metrics", "실행 비교 지표", "运行比较指标", "実行の比較指標", "Métricas de la comparación", "Indicateurs de la comparaison"],
  cmpMetric: ["Metric", "지표", "指标", "指標", "Métrica", "Indicateur"],
  cmpBvsA: ["B vs A ({confidence}% CI)", "B 대 A ({confidence}% 신뢰구간)", "B 对比 A（{confidence}% 置信区间）", "B 対 A（{confidence}% 信頼区間）", "B frente a A (IC {confidence} %)", "B vs A (IC {confidence} %)"],
  cmpChange: ["Change", "변화율", "变化", "変化率", "Cambio", "Variation"],
  cmpProbHint: ["Share of bootstrap draws where B > A", "부트스트랩 표본 중 B > A인 비율", "自助抽样中 B > A 的比例", "ブートストラップ標本のうち B > A となった割合", "Proporción de remuestreos en los que B > A", "Part des tirages bootstrap où B > A"],
  cmpNHint: ["Customers needed to detect a 5% change with 80% power", "검정력 80%로 5% 변화를 감지하는 데 필요한 고객 수", "以 80% 检验效能检测 5% 变化所需的顾客数", "検出力80%で5%の変化を検出するのに必要な顧客数", "Clientes necesarios para detectar un cambio del 5 % con una potencia del 80 %", "Clients nécessaires pour détecter une variation de 5 % avec une puissance de 80 %"],
  cmpZeroBaselineHint: ["A 5% relative change is undefined for a zero baseline.", "기준값이 0이면 5% 상대 변화를 정의할 수 없습니다.", "基准为零时，5% 的相对变化没有定义。", "基準値がゼロの場合、5%の相対変化は定義できません。", "Un cambio relativo del 5 % no está definido con una base cero.", "Une variation relative de 5 % n’est pas définie pour une référence nulle."],
  cmpFootnote: ["{paired} paired customers · {draws} bootstrap draws. With a zero baseline, intervals show absolute changes (conversion in percentage points). Relative sample size estimates are unavailable for a zero baseline.", "짝지은 고객 {paired}명 · 부트스트랩 {draws}회. 기준값이 0이면 신뢰구간은 절대 변화량(구매 전환율은 %p)으로 표시되며, 상대 표본 크기 추정은 제공되지 않습니다.", "{paired} 位配对顾客 · {draws} 次自助抽样。基准为零时，区间显示绝对变化（转化率以百分点表示），且无法估算相对样本量。", "対になった顧客 {paired} 人・ブートストラップ {draws} 回。基準値がゼロの場合、区間は絶対変化（購入率はポイント）で表示され、相対的な必要サンプル数は推定できません。", "{paired} clientes emparejados · {draws} remuestreos bootstrap. Con una base cero, los intervalos muestran cambios absolutos (la conversión en puntos porcentuales) y no hay estimaciones relativas de tamaño muestral.", "{paired} clients appariés · {draws} tirages bootstrap. Avec une référence nulle, les intervalles montrent des variations absolues (la conversion en points de pourcentage) et les estimations relatives de taille d’échantillon ne sont pas disponibles."],
  cmpHeadline: ["Spend per visitor: {change}", "방문객당 지출: {change}", "每位访客消费：{change}", "来店客1人あたり支出：{change}", "Gasto por visitante: {change}", "Dépense par visiteur : {change}"],
  cmpRangeVerdict: ["({low} to {high}) — {verdict}", "({low} ~ {high}) — {verdict}", "（{low} 至 {high}）— {verdict}", "（{low}〜{high}）— {verdict}", "({low} a {high}) — {verdict}", "({low} à {high}) — {verdict}"],
  cmpBetter: ["B is reliably better.", "B가 확실히 더 좋습니다.", "B 确实更好。", "B のほうが確実に良好です。", "B es claramente mejor.", "B est nettement meilleur."],
  cmpWorse: ["B is reliably worse.", "B가 확실히 더 나쁩니다.", "B 确实更差。", "B のほうが確実に劣ります。", "B es claramente peor.", "B est nettement moins bon."],
  cmpNoDiff: ["no reliable difference yet (P(B>A) = {prob}).", "아직 확실한 차이는 없습니다 (P(B>A) = {prob}).", "尚无可靠差异（P(B>A) = {prob}）。", "まだ確かな差はありません（P(B>A) = {prob}）。", "aún no hay una diferencia fiable (P(B>A) = {prob}).", "pas encore d’écart fiable (P(B>A) = {prob})."],
